{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.easyecom_db_returns_intermediate as WITH FlattenedItems AS ( SELECT r.order_id, r.INVOICE_ID, r.REFERENCE_CODE, r.CREDIT_NOTE_ID, r.credit_note_number, r.ORDER_DATE::TIMESTAMP AS ORDER_DATE, r.INVOICE_DATE::TIMESTAMP AS INVOICE_DATE, r.RETURN_DATE::TIMESTAMP AS RETURN_DATE, r.MANIFEST_DATE::TIMESTAMP AS MANIFEST_DATE, r.IMPORT_DATE::TIMESTAMP AS IMPORT_DATE, r.LAST_UPDATE_DATE::TIMESTAMP AS LAST_UPDATE_DATE, r.MARKETPLACE, r.MARKETPLACE_ID, r.REPLACEMENT_ORDER, TRIM(ri.value:suborder_id::STRING, \'\"\') AS SUBORDER_ID, TRIM(ri.value:company_product_id::STRING, \'\"\') AS COMPANY_PRODUCT_ID, TRIM(ri.value:productName::STRING, \'\"\') AS PRODUCTNAME, TRIM(ri.value:product_Id::STRING, \'\"\') AS PRODUCT_ID, TRIM(ri.value:sku::STRING, \'\"\') AS SKU, TRIM(ri.value:return_reason::STRING, \'\"\') AS RETURN_REASON, TRIM(ri.value:inventory_status::STRING, \'\"\') AS INVENTORY_STATUS, ri.value:returned_item_quantity::FLOAT AS RETURNED_QUANTITY, ri.value:credit_note_total_item_excluding_tax::FLOAT AS TOTAL_RETURN_AMOUNT_EXCL_TAX, ri.value:credit_note_total_item_tax::FLOAT AS RETURN_TAX, ri.value:credit_note_total_item_shipping_charge::FLOAT AS RETURN_SHIPPING_CHARGE, ri.value:credit_note_total_item_miscellaneous::FLOAT AS RETURN_MISC FROM maplemonk.easyecom_easyecom_emma_returns AS r, LATERAL FLATTEN(input => r.ITEMS) AS ri ) SELECT fi.*, COALESCE(fi.TOTAL_RETURN_AMOUNT_EXCL_TAX, 0) + COALESCE(fi.RETURN_TAX, 0) + COALESCE(fi.RETURN_SHIPPING_CHARGE, 0) + COALESCE(fi.RETURN_MISC, 0) AS TOTAL_RETURN_AMOUNT FROM FlattenedItems fi QUALIFY ROW_NUMBER() OVER ( PARTITION BY fi.order_id, fi.Invoice_ID, fi.REFERENCE_CODE, fi.SUBORDER_ID, fi.credit_note_id, fi.credit_note_number ORDER BY fi.LAST_UPDATE_DATE DESC ) = 1; create or replace table emmasleep_db.maplemonk.emmasleep_db_returns_consolidated as with returns as ( select r.order_id , r.suborder_id , r.reference_code , r.order_date , r.return_date , r.last_update_date , r.company_product_id , r.productname as product_name , r.product_id , r.sku , r.marketplace , r.marketplace_id , r.replacement_order , r.return_reason , CASE WHEN r.return_reason IN (\'Complaint - Wrong Variant \',\'Complaint-Wrong Product Ordered\',\'Complaint - Unknown\',\'Complaint - Quality Issue\',\'Damage in Transit\',\'Cancelled_after_invoice\',\'Not satisfied: Size issue\') THEN \'Customer Return\' ELSE \'Courier Return\' END AS return_type , CASE WHEN r.inventory_status IN (\'QC Pass\',\'Repair\') THEN \'Good Inventory\' ELSE \'Bad Inventory\' END AS inventory_type , r.total_return_amount , r.TOTAL_RETURN_AMOUNT_EXCL_TAX , r.RETURNED_QUANTITY from maplemonk.easyecom_db_returns_intermediate r ), sales as ( select s.quantity as order_quantity ,s.order_id ,s.marketplace ,s.channel as marketing_channel ,s.name as customer_name ,s.email as customer_email ,s.SHIPPING_LAST_UPDATE_DATE ,s.SHIPPING_STATUS ,s.SALEORDERITEMCODE ,s.reference_code ,s.DELIVERED_DATE ,s.return_flag ,s.returned_quantity ,s.DAYS_IN_SHIPMENT ,s.CITY_FINAL as city ,s.STATE_FINAL as state ,s.pincode ,s.SELLING_PRICE ,s.discount ,s.order_date ,s.PRODUCT_NAME ,s.PRODUCT_ID ,case when s.Payment_Mode in (\'ONLINE\',\'PREPAID\') THEN FALSE when s.Payment_Mode in (\'COD\') then TRUE else null end AS COD_Order , s.sales_order_item_id as suborder_id , s.courier as Shipping_Courier , s.SKU , s.new_customer_flag , s.order_status , LAST_DAY(DATE(s.Order_Date),MONTH) AS MONTH FROM emmasleep_db.maplemonk.emmasleep_db_sales_consolidated s ) select s.month , s.product_name , s.sku , s.order_id , s.suborder_id , s.product_id , \'EMMA SLEEP\' as brand , CAST(s.order_date AS TIMESTAMP) as order_date , s.order_status , s.return_flag , r.return_type , r.inventory_type , r.return_date , r.last_update_date , r.return_reason , r.total_return_amount , r.replacement_order , s.returned_quantity , s.cod_order , s.selling_price , s.SALEORDERITEMCODE , s.reference_code , s.city , s.state , s.pincode , CASE WHEN s.pincode LIKE \'1%\' OR s.pincode LIKE \'2%\' THEN \'North Zone\' WHEN s.pincode LIKE \'3%\' OR s.pincode LIKE \'4%\' THEN \'West Zone\' WHEN s.pincode LIKE \'5%\' OR s.pincode LIKE \'6%\' THEN \'South Zone\' WHEN s.pincode LIKE \'7%\' OR s.pincode LIKE \'8%\' THEN \'East Zone\' ELSE NULL END AS zone , s.shipping_courier , s.customer_name , s.customer_email , s.new_customer_flag , s.marketing_channel , s.marketplace , r.TOTAL_RETURN_AMOUNT_EXCL_TAX from sales s left join returns r on r.order_id = s.order_id and r.suborder_id = s.suborder_id;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from EMMASLEEP_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            